suppressMessages({library(lavaan); library(psych)})
x <- read.csv("derived/epoch_wide_v1.csv"); vl <- paste0(c("gpqa","aime","arc1","arc2","dtb"), "_lg")
x$grp <- factor(ifelse(x$year <= 2025, "le2025", "y2026")); fm <- c("chisq.scaled","df","pvalue.scaled","cfi.robust","rmsea.robust","srmr")
m <- paste("g =~", paste(vl, collapse = " + "))
sink("out/i_epoch_v1.txt")
cat("Epoch AI frontier replication | model groups:", nrow(x), "| orgs:", length(unique(x$org)), "\n"); print(table(x$grp))
cat("\nPairwise-complete correlations (logit scale)\n"); print(round(cor(x[, vl], use = "pairwise"), 2)); print(sapply(vl, function(a) sapply(vl, function(b) sum(complete.cases(x[, c(a, b)])))))
f1 <- cfa(m, data = x, estimator = "MLR", missing = "ml", std.lv = TRUE)
cat("\nOne-factor model, FIML, MLR (no cluster)\n"); print(round(fitMeasures(f1, fm), 3)); print(standardizedSolution(f1)[1:5, c("rhs","est.std","ci.lower","ci.upper")], digits = 3)
f1c <- cfa(m, data = x, estimator = "MLR", missing = "ml", std.lv = TRUE, cluster = "org")
cat("\nSame, organization-clustered (14 clusters)\n"); print(round(fitMeasures(f1c, fm), 3))
eqs <- list(configural = "", metric = "loadings", scalar = c("loadings","intercepts"), strict = c("loadings","intercepts","residuals"))
fits <- lapply(eqs, function(e) cfa(m, data = x, group = "grp", estimator = "MLR", missing = "ml", group.equal = e))
tab <- t(sapply(fits, function(f) round(fitMeasures(f, fm), 3))); cat("\nInvariance <=2025 vs 2026 (FIML, MLR)\n"); print(tab)
cat("Delta CFI:", round(diff(tab[, "cfi.robust"]), 3), " Delta RMSEA:", round(diff(tab[, "rmsea.robust"]), 3), "\n")
print(lavTestLRT(fits$configural, fits$metric, fits$scalar, fits$strict, method = "satorra.bentler.2001"))
sc <- lavTestScore(fits$scalar); u <- sc$uni; pt <- parTable(fits$scalar); u$lab <- paste(pt$lhs[match(u$lhs, pt$plabel)], pt$op[match(u$lhs, pt$plabel)], pt$rhs[match(u$lhs, pt$plabel)])
cat("\nScore tests (scalar)\n"); print(head(u[order(-u$X2), c("lab","X2","p.value")], 8))
cat("\nStandardised loadings by group (configural)\n"); s <- standardizedSolution(fits$configural); print(s[s$op == "=~", c("group","rhs","est.std","se")], digits = 3)
sink()
